// spec: .qa/e2e/specs/add-candidate.md
// seed: tests/seed.hunter_plus.spec.ts
// Nothing is saved: the dialog is closed with «יציאה».
import { test, expect } from '@playwright/test';
import path from 'path';
import { openAddCandidate, closeAddCandidate } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const CV = path.join(__dirname, '../../fixtures/qa-auto-cv-no-salary.pdf');

test.describe('«הוספת מועמד» — CV salary parsing (#344b9a)', () => {
  test('CV without salary leaves the salary fields empty @desktop #344b9a', async ({ page }) => {
    test.setTimeout(150_000);
    // 1. Upload the CV without salary
    const dialog = await openAddCandidate(page);
    await dialog.locator('input[type="file"][accept*="pdf"]').setInputFiles(CV);

    // 2. AI parsing done
    await expect(dialog.getByText(/^מילאנו מקורות החיים/)).toBeVisible({ timeout: 120_000 });

    // Salary fields stay empty — nothing is invented
    await expect(dialog.getByRole('textbox', { name: 'ציפיות שכר מ- (₪)' })).toHaveValue('');
    await expect(dialog.getByRole('textbox', { name: 'ציפיות שכר עד (₪)' })).toHaveValue('');
    // Name filled from the CV
    const first = await dialog.getByRole('textbox', { name: 'שם פרטי (שדה חובה)' }).inputValue();
    const last = await dialog.getByRole('textbox', { name: 'שם משפחה (שדה חובה)' }).inputValue();
    expect(`${first} ${last}`).toContain('QA-AUTO');
    expect(`${first} ${last}`).toContain('Nosalary');

    // 3. Close → «יציאה»
    await closeAddCandidate(page, 'יציאה');
    await expect(dialog).toBeHidden();
  });
});
